 brand-service's filename and type. Up to 5, 10 MB together. FAIL LOUD, nothing sent: unknown or another org's document = 404 `attachment_not_found`; over the limits = 422 `attachment_too_large`; brand-service unreadable = 502 `attachment_unavailable`; a thread on the Instantly pipe (no attachment support) = 422 `attachments_unsupported_on_transport`. Absent or empty = the reply exactly as before. Replies only: cold sequence steps never carry a file."}},"required":["email","body_html"],"example":{"campaign_id":"c1a2b3c4-0000-0000-0000-000000000001","email":"alice@media.com","body_html":"<p>Great — how does Thursday 3pm look?</p>","sent_by":"automation"}},"answers":[{"status":"200","description":"The reply was sent (instantly-service shape)","schema":{"type":"object","properties":{"success":{"type":"boolean","enum":[true]},"status":{"type":"string","enum":["sent"]},"reply":{"type":"object","properties":{"transport":{"type":"string","enum":["instantly","smtp"],"description":"Which pipe carried the reply — the one that carried the outreach"},"instantlyCampaignId":{"type":"string"},"leadEmail":{"type":"string"},"accountEmail":{"type":"string","description":"The mailbox that answered. Resolved by this service, never supplied by the caller."},"from":{"type":"string","description":"The From header as the prospect sees it, persona included"},"subject":{"type":"string","description":"The conversation's own subject under `Re:`"},"cc":{"type":"string","description":"The agency inbox this reply was CC'd to — VISIBLE to the prospect, so a reply-all reaches a human. Never a BCC."},"messageId":{"type":"string","description":"Instantly's email id, or the RFC 5322 Message-Id we sent"},"inReplyTo":{"type":"string","description":"The prospect message this reply threads onto"},"attachments":{"type":"array","items":{"type":"object","properties":{"documentId":{"type":"string","description":"The brand-service offer document id"},"filename":{"type":"string"},"contentType":{"type":"string"},"sizeBytes":{"type":"integer"},"md5":{"type":"string","description":"Hex md5 of the exact bytes attached"}},"required":["documentId","filename","contentType","sizeBytes","md5"]},"description":"The files this reply carried. Absent when it carried none."}},"required":["transport","instantlyCampaignId","leadEmail","accountEmail","from","subject","cc","messageId","inReplyTo"]}},"required":["success","status","reply"]}}],"needsTheirYes":{"why":"Sends a reply to a person in their email thread.","because":["sends_to_person"],"notNeededWhen":[]}}

